import React, { useState } from 'react';
import { Map, MapPin, ChevronRight, ChevronLeft, Search, Box, Info, LayoutGrid, List } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); 
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  // --- MOCK DATA ---
  const data = [
    {
      id: 'Z-101', name: 'NORTH_SECTOR', code: 'NS-01', status: 'Optimal',
      areas: [
        { id: 'A-101-1', name: 'Hillside Drive', location: 'Upper North', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409', 'BN-412'] },
        { id: 'A-101-2', name: 'University Road', location: 'East Campus', code: 'URD-12', bins: ['BN-502', 'BN-503'] }
      ]
    },
    {
      id: 'Z-202', name: 'CENTRAL_HUB', code: 'CH-02', status: 'High Load',
      areas: [
        { id: 'A-202-1', name: 'Main Square', location: 'Downtown', code: 'MSQ-01', bins: ['BN-101', 'BN-102', 'BN-103'] },
        { id: 'A-202-2', name: 'Shopping Plaza', location: 'Midtown', code: 'SPZ-09', bins: ['BN-201', 'BN-205', 'BN-208'] }
      ]
    }
  ];

  // --- LOGIC ---
  const filteredZones = data.filter(z => z.name.includes(searchQuery.toUpperCase()));
  const filteredAreas = selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  // --- UI FRAGMENTS ---
  const Breadcrumb = () => (
    <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-[0.2em] text-[#47510B]/50 mb-4">
      <span className="cursor-pointer hover:text-[#AB1717]" onClick={() => setViewLevel('ZONES')}>DIRECTORY</span>
      {selectedZone && <> <ChevronRight size={12} /> <span className="text-[#AB1717]">{selectedZone.name}</span> </>}
      {selectedArea && <> <ChevronRight size={12} /> <span className="text-[#47510B]">{selectedArea.name}</span> </>}
    </div>
  );

  return (
    <div className="w-full animate-slot flex flex-col">
      <Breadcrumb />

      {/* LEVEL 1: ZONES (GRID VIEW) */}
      {viewLevel === 'ZONES' && (
        <div className="flex flex-col gap-6">
          <div className="flex justify-between items-end border-b-4 border-[#47510B] pb-4">
            <div>
              <h2 className="text-3xl font-black italic text-[#47510B] leading-none uppercase">Sector_Registry</h2>
              <p className="text-[10px] font-bold text-[#AB1717] mt-2 tracking-widest uppercase italic">02_Deployment_Atlas</p>
            </div>
            <div className="relative w-64">
              <Search className="absolute right-3 top-2 text-[#47510B]" size={16} />
              <input 
                type="text" placeholder="FILTER_BY_CODE..." 
                className="w-full bg-white border-2 border-[#47510B] p-2 pr-10 text-[10px] font-black uppercase focus:ring-0 outline-none"
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {filteredZones.map(zone => (
              <div key={zone.id} onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}} 
                className="group cursor-pointer bg-white border-2 border-[#47510B] hover:border-[#AB1717] transition-all flex flex-col p-0 overflow-hidden shadow-[4px_4px_0_0_#47510B] hover:shadow-[4px_4px_0_0_#AB1717]">
                <div className="bg-[#47510B] p-2 flex justify-between items-center group-hover:bg-[#AB1717] transition-colors">
                  <span className="text-[#CAD23C] text-[9px] font-black italic">{zone.code}</span>
                  <ChevronRight size={14} className="text-white" />
                </div>
                <div className="p-4 flex justify-between items-center">
                  <h3 className="text-xl font-black text-[#47510B] tracking-tighter">{zone.name}</h3>
                  <div className="text-right">
                    <p className="text-[10px] font-black uppercase opacity-40">Areas</p>
                    <p className="text-lg font-black leading-none">{zone.areas.length}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* LEVEL 2: AREAS (TECHNICAL TABLE VIEW) */}
      {viewLevel === 'AREAS' && (
        <div className="flex flex-col gap-6">
          <div className="flex items-center gap-4">
            <button onClick={() => setViewLevel('ZONES')} className="bg-[#47510B] text-white p-2 hover:bg-[#AB1717] transition-colors">
              <ChevronLeft size={20} />
            </button>
            <h2 className="text-2xl font-black text-[#47510B] uppercase italic tracking-tighter">{selectedZone.name} <span className="opacity-30">// SUB_AREAS</span></h2>
          </div>

          <div className="bg-white border-4 border-[#47510B] shadow-[8px_8px_0_0_#A1AED1]">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-[#47510B] text-[#CAD23C] text-[9px] font-black uppercase">
                  <th className="p-4 border-r border-[#CAD23C]/20">Area_Name</th>
                  <th className="p-4 border-r border-[#CAD23C]/20">Geo_Location</th>
                  <th className="p-4 border-r border-[#CAD23C]/20">Nodes</th>
                  <th className="p-4 text-right">Action</th>
                </tr>
              </thead>
              <tbody>
                {selectedZone.areas.map(area => (
                  <tr key={area.id} className="border-b border-[#47510B]/10 hover:bg-[#FDFAD8] transition-colors group">
                    <td className="p-4 font-black text-[#47510B] uppercase text-sm italic">{area.name}</td>
                    <td className="p-4 text-[10px] font-bold text-[#47510B]/60 uppercase">{area.location}</td>
                    <td className="p-4 text-[10px] font-black"><span className="bg-[#CAD23C] px-2 py-0.5 border border-[#47510B]">{area.bins.length} UNITS</span></td>
                    <td className="p-4 text-right">
                      <button onClick={() => {setSelectedArea(area); setViewLevel('BINS');}} className="text-[9px] font-black border-2 border-[#47510B] px-3 py-1 hover:bg-[#AB1717] hover:text-white transition-all uppercase italic">Inspect_Nods</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* LEVEL 3: BINS (HARDWARE LIST VIEW) */}
      {viewLevel === 'BINS' && (
        <div className="flex flex-col gap-6">
          <div className="flex items-center gap-4">
             <button onClick={() => setViewLevel('AREAS')} className="bg-[#AB1717] text-white p-2 border-2 border-[#47510B] shadow-[2px_2px_0_0_#47510B]">
                <ChevronLeft size={20} />
             </button>
             <div>
                <h2 className="text-2xl font-black text-[#47510B] uppercase leading-none italic">{selectedArea.name}</h2>
                <p className="text-[10px] font-bold text-[#AB1717] uppercase tracking-widest mt-1">Area_Code: {selectedArea.code}</p>
             </div>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
            {selectedArea.bins.map(bin => (
              <div key={bin} className="bg-white border-2 border-[#47510B] p-4 flex flex-col items-center gap-2 group hover:bg-[#CAD23C] transition-all cursor-crosshair">
                <Box size={18} className="text-[#AB1717] group-hover:scale-110 transition-transform" />
                <span className="text-[10px] font-black text-[#47510B]">{bin}</span>
                <div className="w-full h-[2px] bg-[#47510B]/10 group-hover:bg-[#47510B]/30" />
                <span className="text-[7px] font-bold opacity-40 uppercase">TELEMETRY_ON</span>
              </div>
            ))}
          </div>

          <div className="mt-4 p-4 border-l-4 border-[#AB1717] bg-[#A1AED1]/20 flex items-start gap-3">
             <Info size={16} className="text-[#AB1717] mt-0.5" />
             <p className="text-[9px] font-bold text-[#47510B] leading-relaxed uppercase opacity-70">
                Authorized access only. All bin hardware IDs listed above are reporting live to the master telemetry server. 
                Discrepancies in Node_Serial counts should be reported to system admin.
             </p>
          </div>
        </div>
      )}
    </div>
  );
};

export default AreasZonesTab;
